import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.3 prerelease","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.3 prerelease","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","order":30},"headers":[],"relativePath":"en/releases/4.2.1-rc.3.md","filePath":"en/releases/4.2.1-rc.3.md","lastUpdated":1794591482000}'),o={name:"en/releases/4.2.1-rc.3.md"};function s(n,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">Goal, release status and prerequisites <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;Goal, release status and prerequisites {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>RC3 is a published prerelease, as reported on 13 November 2026. Use it to evaluate the Linux desktop changes following RC2, with a backup and a separate test profile. It is a candidate rather than a stable-channel update. Download the published AppImage, DEB or portable asset and its <code>SHA256SUMS.txt</code> from the <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">release list</a>; the recorded packages were built locally.</p><p>Cloud section recovery and collaboration remain experimental. The installation does not deploy backend migrations or establish production account compatibility.</p><h2 id="changes-available-in-rc3" tabindex="-1">Changes available in RC3 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;Changes available in RC3 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>Retains RC2&#39;s correction for concurrent comparison reads and local retry with the native failure reason.</li><li>Variables persist text, number, boolean, list and local-secret types. Atomic saves reject a changed host or stale editor revision, preserving existing template text rendering.</li><li>Secrets remain masked. Switching hosts cannot fall back to a legacy write, and native classification excludes values queued before they became secret from later publication and comparison output.</li><li>The native Variables bridge supports cached comparison, explicit one-variable adoption and cache-only download. Application rechecks session, consent, local revision and cache entry.</li></ul><p>Saving Variables remains local. RC3 does not expose the complete Variables Changes button with reviewed send/withdraw and pending-conflict handling; that section integration is described in <a href="./4.2.2.html">4.2.2&#39;s source notes</a>. Marking a local value secret does not erase a previously published Cloud copy.</p><h2 id="check-the-published-candidate" tabindex="-1">Check the published candidate <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;Check the published candidate {#check-the-published-candidate}&quot;">​</a></h2><ol><li>Verify the package checksum and displayed <code>4.2.1-rc.3</code> version. Keep test profile and XDG directories separate from your normal profile.</li><li>Create a harmless text variable such as <code>demoGreeting = &quot;Hello&quot;</code>, save and reload it. Check the other explicit types with non-sensitive sample values.</li><li>Open Changes and exercise loading/local retry. Inspect Settings/Teams and optional guided help without treating missing backend capabilities as successful setup.</li><li>Report the exact action, version, native reason and request ID for any failure. Keep tokens, invitation codes and secret values out of reports.</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">Expected result, evidence and recovery <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;Expected result, evidence and recovery {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>Typed local values should survive reload, while stale-host or stale-revision edits fail visibly. The original record reports native Variables/sync/parity checks, fake-host browser tests, sandbox CLI verification, installer content checks and frontend-ready startup with an empty isolated profile. It does not demonstrate signed-in production sync or media playback.</p><p>The recorded AppImage SHA-256 is <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code>; verify the checksum file accompanying your download. On failure, preserve the copied profile and use <a href="./../user/preferences/troubleshooting.html">troubleshooting</a> before retrying recovery actions.</p><p>Nickname invitations depend on backend <code>6a69c99</code> and migration <code>20261113000001_remote_invitation_recipients.sql</code>. The old record observed a missing people route; no new production probe is claimed here. Automations Cloud transport, Overlay revisions and the remaining collaboration audit were unfinished, and the historical SQLite lock holder remained unknown.</p><p>The <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">original release record</a> is retained as dated evidence. Return to the <a href="./">release index</a>.</p>',14)])])}const b=a(o,[["render",s]]);export{u as __pageData,b as default};
